export function webDeterministicChecks(candidate,source,sourceFileSha256){
 const errors=[],check=(ok,m)=>{if(!ok)errors.push(m);};
 check(candidate.schema==='coach-textbook-web-article-draft/1'&&candidate.status==='draft','web_candidate_schema');
 const cp={...candidate};delete cp.candidateSha256;check(candidate.candidateSha256===sha(JSON.stringify(cp)),'web_candidate_internal_digest');
 for(const field of ['sourceId','articleId','url','title','language','fetchedAt'])check(candidate.source?.[field]===source[field],`web_source_${field}`);
 check(candidate.source?.sourceSha256===sourceFileSha256&&candidate.source?.htmlSha256===source.html.sha256&&candidate.source?.mainSha256===source.main.sha256,'web_source_hash_binding');
 check(candidate.body?.language==='zh-CN'&&candidate.body?.mode===(source.language==='zh-CN'?'verbatim':'translated')&&candidate.body?.flowOrder==='source-dom-order','web_body_mode');
 const blocks=candidate.body?.blocks??[],figures=candidate.figures??[],sourceBlocks=source.blocks??[];
 check(same(blocks.flatMap(b=>b.sourceBlockIds??[]),sourceBlocks.map(b=>b.id)),'web_dom_order_complete_unique_coverage');
 check(new Set(figures.map(f=>f.figureId)).size===figures.length,'web_duplicate_figure');
 check(same(blocks.filter(b=>b.type==='figure').map(b=>b.figureId),figures.map(f=>f.figureId)),'web_figure_flow_coverage_order');
 for(const block of blocks){
  const original=sourceBlocks.find(b=>b.id===block.sourceBlockIds?.[0]);
  check(block.sourceBlockIds?.length===1&&Boolean(original),'web_source_single_block_reference');if(!original)continue;
  check(block.paragraphId===original.paragraphId&&same(block.tableContext,original.tableContext),'web_paragraph_table_binding:'+original.id);
  if(original.type==='text'){
   check(block.type==='text'&&block.sourceText===original.text&&same(block.sourceSegments,original.segments),'web_text_marks_links_binding:'+original.id);
   check(typeof block.text==='string'&&(!original.text.trim()||Boolean(block.text.trim())),'web_empty_translation:'+original.id);
   if(source.language==='zh-CN')check(block.text===original.text||inlineTextAllowed(candidate.provenance.revision?.inlineJapanese?.plan,original.id,original.text,block.text),'web_chinese_rewritten:'+original.id);
   else check(!/\[(?:牌形|牌|手牌|待补|省略)\]|[（(](?:接上段|承接上一句|同上|略)[）)]/.test(block.text??''),'web_translation_placeholder:'+original.id);
  }else{
   const figure=figures.find(f=>f.figureId===block.figureId);check(block.type==='figure'&&Boolean(figure),'web_missing_figure:'+original.id);if(!figure)continue;
   check(same(figure.sourceBlockIds,[original.id])&&same(figure.sourceOccurrenceIds,original.images.map(i=>i.occurrenceId)),'web_image_occurrence_coverage:'+original.id);
   const ids=original.images.map(i=>i.assetId);
   check(same(figure.sourceAssetBindings?.map(a=>a.assetId),ids),'web_figure_assets_complete:'+original.id);
   for(const a of figure.sourceAssetBindings??[]){const asset=source.assets.find(s=>s.assetId===a.assetId);check(Boolean(asset)&&a.path===`web-sources/v1/${asset.path}`&&a.sha256===asset.sha256&&a.url===asset.url,'web_figure_asset_binding:'+a.assetId);}
   check(typeof figure.transcription==='string'&&Boolean(figure.transcription.trim())&&!/\[(?:牌形|牌|手牌|待补|省略)\]/.test(figure.transcription),'web_figure_transcription:'+figure.figureId);
  }
 }
 return {passed:errors.length===0,errors,textBlocks:sourceBlocks.filter(b=>b.type==='text').length,imageRuns:sourceBlocks.filter(b=>b.type==='image-run').length,imageOccurrences:sourceBlocks.flatMap(b=>b.images??[]).length,figures:figures.length};
}

async function verifySource(processingRoot,candidate){
 const path=bound(processingRoot,candidate.source.sourcePath),bytes=await readFile(path),source=JSON.parse(bytes);
 const checks=webDeterministicChecks(candidate,source,sha(bytes));if(!checks.passed)throw Error('web_candidate_checks:'+checks.errors.join('|'));
 const independentSource=await runPython([new URL('./textbook-audit-web-source.py',import.meta.url).pathname.replace(/^\/([A-Za-z]:)/,'$1'),'--processing-root',processingRoot,'--source',path]);
 if(!independentSource.passed)throw Error('web_independent_source_checks:'+independentSource.errors.join('|'));
 if(candidate.provenance?.extractorSha256!==source.extractorSha256)throw Error('web_extractor_binding');
 if(candidate.provenance?.reuseMap){const binding=candidate.provenance.reuseMap,bytes=await readFile(bound(processingRoot,binding.path)),map=JSON.parse(bytes);if(sha(bytes)!==binding.sha256||map.schema!=='coach-textbook-exact-web-reuse/1'||map.sourceFileSha256!==candidate.source.sourceSha256)throw Error('web_reuse_map_changed');}
 return {source,checks,independentSource};
}

